            ["swap", old, new] if swap.is_none() => swap = Some(((*old).to_string(), (*new).to_string())),
            ["push", value] if push.is_none() => push = Some((*value).to_string()),
            _ => return None,
        }
    }
    let heat = match mode? {
        "heat" => true,
        "peek" => false,
        _ => return None,
    };
    let (old, new, extra) = if heat {
        let (old, new) = swap?;
        (old, new, push?)
    } else {
        if swap.is_some() || push.is_some() { return None; }
        (String::new(), String::new(), String::new())
    };
    let cells = cells?;
