    let Some(frost_bag) = values(&frost.ids.borrow(), &frost.cells) else { return 1; };
    let Some(live_bag) = values(&sess.ids.borrow(), &pool.cells) else { return 1; };
    if heat && frost_bag == live_bag { return 1; }
    let extra = tally::lines();
    let body = format!(
        "{{\"tick\":{},\"mark\":{},\"frost_bag\":{},\"live_bag\":{}}}\n",
        sess.n0.saturating_add(extra), sess.n1, pack(&frost_bag), pack(&live_bag)
    );
